/* saleson.shop.item.ItemFrontMapper.getFrontItemCountForNewPolicy 답례품 전체 목록 개수 조회 */ SELECT COUNT(1) FROM ( SELECT 1 FROM OP_ITEM I JOIN OP_SELLER S ON I.SELLER_ID = S.SELLER_ID JOIN G_LOCGOV L ON S.LOCGOV_CODE = L.LOCGOV_CODE JOIN OP_ITEM_CATEGORY IC ON I.ITEM_ID = IC.ITEM_ID JOIN OP_CATEGORY C ON IC.CATEGORY_ID = C.CATEGORY_ID JOIN OP_CATEGORY_GROUP G ON C.CATEGORY_GROUP_ID = G.CATEGORY_GROUP_ID LEFT JOIN OP_ITEM_OPTION_SOLDOUT T ON I.ITEM_ID = T.ITEM_ID WHERE 1=1 AND I.DATA_STATUS_CODE = '1' AND I.DISPLAY_FLAG = 'Y' AND I.ITEM_DATA_TYPE = '1' AND I.ITEM_TYPE IN ('1', '3') AND I.PRIVATE_TYPE IN ('000') AND S.STATUS_CODE = '2' AND C.CATEGORY_FLAG = 'Y' AND G.CATEGORY_GROUP_FLAG = 'Y' AND 'N' = ( CASE WHEN I.SOLD_OUT = '1' THEN 'Y' WHEN I.ITEM_OPTION_FLAG = 'N' AND I.STOCK_FLAG = 'Y' AND I.STOCK_QUANTITY = 0 THEN 'Y' WHEN I.ITEM_OPTION_FLAG = 'Y' AND I.ITEM_OPTION_TYPE = 'T' AND I.STOCK_FLAG = 'Y' AND I.STOCK_QUANTITY = 0 THEN 'Y' WHEN I.ITEM_OPTION_FLAG = 'Y' AND T.ITEM_OPTION_SOLD_OUT_FLAG = 'Y' THEN 'Y' ELSE 'N' END )
AND ( I.ITEM_NAME LIKE CONCAT('%', replace(#{keyword},' ', '%'), '%') OR (I.ITEM_KEYWORD LIKE CONCAT('%', replace(#{keyword}, ' ', '%') ,'%')) )
GROUP BY I.ITEM_ID )

/* saleson.shop.item.ItemFrontMapper.getFrontItemTypecListCount	답례품 전체 카테고리, 금액별 목록 개수 조회 */




	  SELECT COUNT(1)
		FROM (
			SELECT
				1
			FROM OP_ITEM I
				JOIN OP_SELLER S ON I.SELLER_ID = S.SELLER_ID
				JOIN G_LOCGOV L ON S.LOCGOV_CODE = L.LOCGOV_CODE
			    JOIN OP_ITEM_CATEGORY IC ON I.ITEM_ID = IC.ITEM_ID
			    JOIN OP_CATEGORY C ON IC.CATEGORY_ID = C.CATEGORY_ID
			    JOIN OP_CATEGORY_GROUP G ON C.CATEGORY_GROUP_ID = G.CATEGORY_GROUP_ID
				LEFT JOIN OP_ITEM_OPTION_SOLDOUT T ON I.ITEM_ID = T.ITEM_ID
			WHERE 1=1
				AND I.DATA_STATUS_CODE = '1'
				AND I.DISPLAY_FLAG = 'Y'
				AND I.ITEM_DATA_TYPE = '1'
				AND I.ITEM_TYPE IN ('1', '3')
				AND I.PRIVATE_TYPE IN ('000')
				AND S.STATUS_CODE = '2'
				AND C.CATEGORY_FLAG = 'Y'
				AND G.CATEGORY_GROUP_FLAG = 'Y'

				AND G.CODE = #{group}							


				AND C.CATEGORY_URL = #{category}						


						AND C.CATEGORY_CLASS1 = #{categoryClass1}


						AND C.CATEGORY_CLASS1 = #{categoryClass1}
						AND C.CATEGORY_CLASS2 = #{categoryClass2}


						AND C.CATEGORY_CLASS1 = #{categoryClass1}
						AND C.CATEGORY_CLASS2 = #{categoryClass2}
						AND C.CATEGORY_CLASS3 = #{categoryClass3}


						AND C.CATEGORY_CLASS1 = #{categoryClass1}
						AND C.CATEGORY_CLASS2 = #{categoryClass2}
						AND C.CATEGORY_CLASS3 = #{categoryClass3}
						AND C.CATEGORY_CLASS4 = #{categoryClass4}





					AND I.SALE_PRICE  >=  50000			



						AND I.SALE_PRICE  <=  #{price}			



		  GROUP BY I.ITEM_ID
	  )

/* saleson.shop.item.ItemFrontMapper.getFrontItemTypecListCountForNewPolicy	답례품 전체 카테고리, 금액별 목록 개수 조회 */
	  SELECT COUNT(1)
		FROM (
			SELECT
				1
			FROM OP_ITEM I
				JOIN OP_SELLER S ON I.SELLER_ID = S.SELLER_ID
				JOIN G_LOCGOV L ON S.LOCGOV_CODE = L.LOCGOV_CODE
			    JOIN OP_ITEM_CATEGORY IC ON I.ITEM_ID = IC.ITEM_ID
			    JOIN OP_CATEGORY C ON IC.CATEGORY_ID = C.CATEGORY_ID
			    JOIN OP_CATEGORY_GROUP G ON C.CATEGORY_GROUP_ID = G.CATEGORY_GROUP_ID
				LEFT JOIN OP_ITEM_OPTION_SOLDOUT T ON I.ITEM_ID = T.ITEM_ID
			WHERE 1=1
				AND I.DATA_STATUS_CODE = '1'
				AND I.DISPLAY_FLAG = 'Y'
				AND I.ITEM_DATA_TYPE = '1'
				AND I.ITEM_TYPE IN ('1', '3')
				AND I.PRIVATE_TYPE IN ('000')
				AND S.STATUS_CODE = '2'
				AND C.CATEGORY_FLAG = 'Y'
				AND G.CATEGORY_GROUP_FLAG = 'Y'
				AND 'N' =
				(
					CASE
						WHEN I.SOLD_OUT = '1' THEN 'Y'
						WHEN I.ITEM_OPTION_FLAG = 'N' AND I.STOCK_FLAG = 'Y' AND I.STOCK_QUANTITY = 0 THEN 'Y'
						WHEN I.ITEM_OPTION_FLAG = 'Y' AND I.ITEM_OPTION_TYPE = 'T' AND I.STOCK_FLAG = 'Y' AND I.STOCK_QUANTITY = 0 THEN 'Y'
						WHEN I.ITEM_OPTION_FLAG = 'Y' AND T.ITEM_OPTION_SOLD_OUT_FLAG = 'Y' THEN 'Y'
						ELSE 'N'
					END
				)

				AND G.CODE = #{group}							


				AND C.CATEGORY_URL = #{category}						


						AND C.CATEGORY_CLASS1 = #{categoryClass1}


						AND C.CATEGORY_CLASS1 = #{categoryClass1}
						AND C.CATEGORY_CLASS2 = #{categoryClass2}


						AND C.CATEGORY_CLASS1 = #{categoryClass1}
						AND C.CATEGORY_CLASS2 = #{categoryClass2}
						AND C.CATEGORY_CLASS3 = #{categoryClass3}


						AND C.CATEGORY_CLASS1 = #{categoryClass1}
						AND C.CATEGORY_CLASS2 = #{categoryClass2}
						AND C.CATEGORY_CLASS3 = #{categoryClass3}
						AND C.CATEGORY_CLASS4 = #{categoryClass4}





					AND I.SALE_PRICE  >=  50000			


					AND I.SALE_PRICE BETWEEN 30000 AND 50000			


					AND I.SALE_PRICE BETWEEN 10000 AND 30000			



						AND I.SALE_PRICE  <=  #{price}			



		  GROUP BY I.ITEM_ID
	  )

/* saleson.shop.item.ItemFrontMapper.getFrontItemTypecList 답례품 전체 카테고리, 금액별 목록 조회 */
SELECT I.ITEM_ID, I.SELLER_ID, I.ITEM_CODE, I.ITEM_USER_CODE, I.ITEM_NAME, I.ITEM_SUMMARY, I.ITEM_DATA_TYPE, I.ITEM_TYPE, I.ITEM_NEW_FLAG, I.ITEM_LABEL, I.ITEM_TYPE1, I.ITEM_TYPE2, I.ITEM_TYPE3, I.ITEM_TYPE4, I.ITEM_TYPE5, I.ITEM_TYPE6, I.ITEM_TYPE7, I.ITEM_TYPE8, I.ITEM_TYPE9, I.ITEM_TYPE10, I.SOLD_OUT, I.STOCK_FLAG, I.STOCK_QUANTITY, I.TAX_TYPE,
I.ITEM_PRICE, I.COST_PRICE, I.SUPPLY_PRICE, I.SALE_PRICE,
I.ADULT_ITEM_YN, I.MOBILE_ITEM_YN,
I.ITEM_IMAGE, I.ITEM_OPTION_FLAG, I.ITEM_OPTION_TYPE, I.ITEM_OPTION_TITLE1, I.ITEM_OPTION_TITLE2, I.ITEM_OPTION_TITLE3, I.DATA_STATUS_CODE, I.DISPLAY_FLAG,
I.STOCK_CODE, I.STOCK_SCHEDULE_AUTO_FLAG, I.STOCK_SCHEDULE_TYPE, I.STOCK_SCHEDULE_DATE, I.STOCK_SCHEDULE_TEXT, I.ORDER_MIN_QUANTITY, I.ORDER_MAX_QUANTITY, I.SALE_QUANTITY,
I.CREATED_DATE, IC.CATEGORY_ID, ( CASE WHEN I.SOLD_OUT = '1' THEN 'Y' WHEN I.ITEM_OPTION_FLAG = 'N' AND I.STOCK_FLAG = 'Y' AND I.STOCK_QUANTITY = 0 THEN 'Y' WHEN I.ITEM_OPTION_FLAG = 'Y' AND I.ITEM_OPTION_TYPE = 'T' AND I.STOCK_FLAG = 'Y' AND I.STOCK_QUANTITY = 0 THEN 'Y' WHEN I.ITEM_OPTION_FLAG = 'Y' AND T.ITEM_OPTION_SOLD_OUT_FLAG = 'Y' THEN 'Y' ELSE 'N' END ) AS ITEM_SOLD_OUT_FLAG, IFNULL(T.ITEM_OPTION_SOLD_OUT_FLAG,'N') AS ITEM_OPTION_SOLD_OUT_FLAG, CONCAT(L.UPPER_LOCGOV_NM,' ',L.LOCGOV_NM) AS LOCGOV_NM, S.LOCGOV_CODE FROM OP_ITEM I JOIN OP_SELLER S ON I.SELLER_ID = S.SELLER_ID JOIN G_LOCGOV L ON S.LOCGOV_CODE = L.LOCGOV_CODE JOIN OP_ITEM_CATEGORY IC ON I.ITEM_ID = IC.ITEM_ID JOIN OP_CATEGORY C ON IC.CATEGORY_ID = C.CATEGORY_ID JOIN OP_CATEGORY_GROUP G ON C.CATEGORY_GROUP_ID = G.CATEGORY_GROUP_ID LEFT JOIN OP_ITEM_OPTION_SOLDOUT T ON I.ITEM_ID = T.ITEM_ID WHERE 1=1 AND I.DATA_STATUS_CODE = '1' AND I.DISPLAY_FLAG = 'Y' AND I.ITEM_DATA_TYPE = '1' AND I.ITEM_TYPE IN ('1', '3') AND I.PRIVATE_TYPE IN ('000') AND S.STATUS_CODE = '2' AND C.CATEGORY_FLAG = 'Y' AND G.CATEGORY_GROUP_FLAG = 'Y'
AND G.CODE = #{group}
AND C.CATEGORY_URL = #{category}
AND C.CATEGORY_CLASS1 = #{categoryClass1}
AND C.CATEGORY_CLASS1 = #{categoryClass1} AND C.CATEGORY_CLASS2 = #{categoryClass2}
AND C.CATEGORY_CLASS1 = #{categoryClass1} AND C.CATEGORY_CLASS2 = #{categoryClass2} AND C.CATEGORY_CLASS3 = #{categoryClass3}
AND C.CATEGORY_CLASS1 = #{categoryClass1} AND C.CATEGORY_CLASS2 = #{categoryClass2} AND C.CATEGORY_CLASS3 = #{categoryClass3} AND C.CATEGORY_CLASS4 = #{categoryClass4}
AND I.SALE_PRICE >= 50000
AND I.SALE_PRICE <= #{price}
GROUP BY I.ITEM_ID
ORDER BY RANDOM()

/* saleson.shop.item.ItemFrontMapper.getFrontItemTypelListCount	지자체몰(카테고리, 금액별 포함) 목록 카운트 조회 */




	  SELECT COUNT(1)
		FROM (
			SELECT
				1
			FROM OP_ITEM I
				JOIN OP_SELLER S ON I.SELLER_ID = S.SELLER_ID
				JOIN G_LOCGOV L ON S.LOCGOV_CODE = L.LOCGOV_CODE
			    JOIN OP_ITEM_CATEGORY IC ON I.ITEM_ID = IC.ITEM_ID
			    JOIN OP_CATEGORY C ON IC.CATEGORY_ID = C.CATEGORY_ID
			    JOIN OP_CATEGORY_GROUP G ON C.CATEGORY_GROUP_ID = G.CATEGORY_GROUP_ID
				LEFT JOIN OP_ITEM_OPTION_SOLDOUT T ON I.ITEM_ID = T.ITEM_ID
			WHERE 1=1
				AND I.DATA_STATUS_CODE = '1'
				AND I.DISPLAY_FLAG = 'Y'
				AND I.ITEM_DATA_TYPE = '1'
				AND I.ITEM_TYPE IN ('1', '3')
				AND I.PRIVATE_TYPE IN ('000')
				AND S.STATUS_CODE = '2'
				AND C.CATEGORY_FLAG = 'Y'
				AND G.CATEGORY_GROUP_FLAG = 'Y'

				AND I.ITEM_NAME LIKE CONCAT('%', #{keyword}, '%')


				AND G.CODE = #{group}							


				AND C.CATEGORY_URL = #{category}						


						AND C.CATEGORY_CLASS1 = #{categoryClass1}


						AND C.CATEGORY_CLASS1 = #{categoryClass1}
						AND C.CATEGORY_CLASS2 = #{categoryClass2}


						AND C.CATEGORY_CLASS1 = #{categoryClass1}
						AND C.CATEGORY_CLASS2 = #{categoryClass2}
						AND C.CATEGORY_CLASS3 = #{categoryClass3}


						AND C.CATEGORY_CLASS1 = #{categoryClass1}
						AND C.CATEGORY_CLASS2 = #{categoryClass2}
						AND C.CATEGORY_CLASS3 = #{categoryClass3}
						AND C.CATEGORY_CLASS4 = #{categoryClass4}





					AND I.SALE_PRICE  >=  50000			



						AND I.SALE_PRICE  <=  #{price}			




		  		AND L.UPPER_LOCGOV_CODE = SUBSTR(#{locgov}, 2)


 		   		AND S.LOCGOV_CODE = #{locgov}

		  GROUP BY I.ITEM_ID
	  )

/* saleson.shop.item.ItemFrontMapper.getFrontItemTypelListCountForNewPolicy	지자체몰(카테고리, 금액별 포함) 목록 카운트 조회 */
