				AND C.CATEGORY_FLAG = 'Y'
				AND G.CATEGORY_GROUP_FLAG = 'Y'
				AND 'N' =
				(
					CASE
						WHEN I.SOLD_OUT = '1' THEN 'Y'
						WHEN I.ITEM_OPTION_FLAG = 'N' AND I.STOCK_FLAG = 'Y' AND I.STOCK_QUANTITY = 0 THEN 'Y'
						WHEN I.ITEM_OPTION_FLAG = 'Y' AND I.ITEM_OPTION_TYPE = 'T' AND I.STOCK_FLAG = 'Y' AND I.STOCK_QUANTITY = 0 THEN 'Y'
						WHEN I.ITEM_OPTION_FLAG = 'Y' AND T.ITEM_OPTION_SOLD_OUT_FLAG = 'Y' THEN 'Y'
						ELSE 'N'
					END
				)

				AND I.ITEM_NAME LIKE CONCAT('%', #{keyword}, '%')


				AND G.CODE = #{group}							


				AND C.CATEGORY_URL = #{category}						


