						AND C.CATEGORY_CLASS2 = #{categoryClass2}
						AND C.CATEGORY_CLASS3 = #{categoryClass3}
						AND C.CATEGORY_CLASS4 = #{categoryClass4}





					AND I.SALE_PRICE  >=  50000			


					AND I.SALE_PRICE BETWEEN 30000 AND 50000			


					AND I.SALE_PRICE BETWEEN 10000 AND 30000			



						AND I.SALE_PRICE  <=  #{price}			




		  		AND L.UPPER_LOCGOV_CODE = SUBSTR(#{locgov}, 2)


 		   		AND S.LOCGOV_CODE = #{locgov}

		  GROUP BY I.ITEM_ID
	  )

/* saleson.shop.item.ItemFrontMapper.getFrontItemTypelList 지자체몰(카테고리, 금액별) 목록 조회 */
SELECT I.ITEM_ID, I.SELLER_ID, I.ITEM_CODE, I.ITEM_USER_CODE, I.ITEM_NAME, I.ITEM_SUMMARY, I.ITEM_DATA_TYPE, I.ITEM_TYPE, I.ITEM_NEW_FLAG, I.ITEM_LABEL, I.ITEM_TYPE1, I.ITEM_TYPE2, I.ITEM_TYPE3, I.ITEM_TYPE4, I.ITEM_TYPE5, I.ITEM_TYPE6, I.ITEM_TYPE7, I.ITEM_TYPE8, I.ITEM_TYPE9, I.ITEM_TYPE10, I.SOLD_OUT, I.STOCK_FLAG, I.STOCK_QUANTITY, I.TAX_TYPE, I.ITEM_PRICE, I.COST_PRICE, I.SUPPLY_PRICE, I.SALE_PRICE, I.ADULT_ITEM_YN, I.MOBILE_ITEM_YN, I.ITEM_IMAGE, I.ITEM_OPTION_FLAG, I.ITEM_OPTION_TYPE, I.ITEM_OPTION_TITLE1, I.ITEM_OPTION_TITLE2, I.ITEM_OPTION_TITLE3, I.DATA_STATUS_CODE, I.DISPLAY_FLAG, I.STOCK_CODE, I.STOCK_SCHEDULE_AUTO_FLAG, I.STOCK_SCHEDULE_TYPE, I.STOCK_SCHEDULE_DATE, I.STOCK_SCHEDULE_TEXT, I.ORDER_MIN_QUANTITY, I.ORDER_MAX_QUANTITY, I.SALE_QUANTITY, I.CREATED_DATE, IC.CATEGORY_ID, ( CASE WHEN I.SOLD_OUT = '1' THEN 'Y' WHEN I.ITEM_OPTION_FLAG = 'N' AND I.STOCK_FLAG = 'Y' AND I.STOCK_QUANTITY = 0 THEN 'Y' WHEN I.ITEM_OPTION_FLAG = 'Y' AND I.ITEM_OPTION_TYPE = 'T' AND I.STOCK_FLAG = 'Y' AND I.STOCK_QUANTITY = 0 THEN 'Y' WHEN I.ITEM_OPTION_FLAG = 'Y' AND T.ITEM_OPTION_SOLD_OUT_FLAG = 'Y' THEN 'Y' ELSE 'N' END ) AS ITEM_SOLD_OUT_FLAG, S.LOCGOV_CODE, IFNULL(T.ITEM_OPTION_SOLD_OUT_FLAG,'N') AS ITEM_OPTION_SOLD_OUT_FLAG, CONCAT(L.UPPER_LOCGOV_NM,' ',L.LOCGOV_NM) AS LOCGOV_NM , IFNULL(LRGM.SORT_SEQ, 5) AS SORT_SEQ1 FROM OP_ITEM I JOIN OP_SELLER S ON I.SELLER_ID = S.SELLER_ID JOIN G_LOCGOV L ON S.LOCGOV_CODE = L.LOCGOV_CODE JOIN OP_ITEM_CATEGORY IC ON I.ITEM_ID = IC.ITEM_ID JOIN OP_CATEGORY C ON IC.CATEGORY_ID = C.CATEGORY_ID JOIN OP_CATEGORY_GROUP G ON C.CATEGORY_GROUP_ID = G.CATEGORY_GROUP_ID LEFT JOIN OP_ITEM_OPTION_SOLDOUT T ON I.ITEM_ID = T.ITEM_ID LEFT JOIN G_LCLGV_RPRS_GDS_MNG LRGM ON S.LOCGOV_CODE = LRGM.LCLGV_CD AND I.ITEM_ID = LRGM.GDS_ID WHERE 1=1 AND I.DATA_STATUS_CODE = '1' AND I.DISPLAY_FLAG = 'Y' AND I.ITEM_DATA_TYPE = '1' AND I.ITEM_TYPE IN ('1', '3') AND I.PRIVATE_TYPE IN ('000') AND S.STATUS_CODE = '2' AND C.CATEGORY_FLAG = 'Y' AND G.CATEGORY_GROUP_FLAG = 'Y'
AND I.ITEM_NAME LIKE CONCAT('%', #{keyword}, '%')
AND G.CODE = #{group}
AND C.CATEGORY_URL = #{category}
AND C.CATEGORY_CLASS1 = #{categoryClass1}
AND C.CATEGORY_CLASS1 = #{categoryClass1} AND C.CATEGORY_CLASS2 = #{categoryClass2}
AND C.CATEGORY_CLASS1 = #{categoryClass1} AND C.CATEGORY_CLASS2 = #{categoryClass2} AND C.CATEGORY_CLASS3 = #{categoryClass3}
AND C.CATEGORY_CLASS1 = #{categoryClass1} AND C.CATEGORY_CLASS2 = #{categoryClass2} AND C.CATEGORY_CLASS3 = #{categoryClass3} AND C.CATEGORY_CLASS4 = #{categoryClass4}
AND I.SALE_PRICE >= 50000
AND I.SALE_PRICE <= #{price}
AND L.UPPER_LOCGOV_CODE = SUBSTR(#{locgov}, 2)
AND S.LOCGOV_CODE = #{locgov}
GROUP BY I.ITEM_ID
ORDER BY SORT_SEQ1 ASC
, I.CREATED_DATE DESC
, I.CREATED_DATE ASC
, I.SALE_PRICE DESC
, I.SALE_PRICE ASC
ORDER BY RANDOM()
, I.CREATED_DATE DESC

/* saleson.shop.item.ItemFrontMapper.getFrontItemTypelList 지자체몰(카테고리, 금액별) 목록 조회 */ SELECT I.ITEM_ID, I.SELLER_ID, I.ITEM_CODE, I.ITEM_USER_CODE, I.ITEM_NAME, I.ITEM_SUMMARY, I.ITEM_DATA_TYPE, I.ITEM_TYPE, I.ITEM_NEW_FLAG, I.ITEM_LABEL, I.ITEM_TYPE1, I.ITEM_TYPE2, I.ITEM_TYPE3, I.ITEM_TYPE4, I.ITEM_TYPE5, I.ITEM_TYPE6, I.ITEM_TYPE7, I.ITEM_TYPE8, I.ITEM_TYPE9, I.ITEM_TYPE10, I.SOLD_OUT, I.STOCK_FLAG, I.STOCK_QUANTITY, I.TAX_TYPE, I.ITEM_PRICE, I.COST_PRICE, I.SUPPLY_PRICE, I.SALE_PRICE, I.ADULT_ITEM_YN, I.MOBILE_ITEM_YN, I.ITEM_IMAGE, I.ITEM_OPTION_FLAG, I.ITEM_OPTION_TYPE, I.ITEM_OPTION_TITLE1, I.ITEM_OPTION_TITLE2, I.ITEM_OPTION_TITLE3, I.DATA_STATUS_CODE, I.DISPLAY_FLAG, I.STOCK_CODE, I.STOCK_SCHEDULE_AUTO_FLAG, I.STOCK_SCHEDULE_TYPE, I.STOCK_SCHEDULE_DATE, I.STOCK_SCHEDULE_TEXT, I.ORDER_MIN_QUANTITY, I.ORDER_MAX_QUANTITY, I.SALE_QUANTITY, I.CREATED_DATE, IC.CATEGORY_ID, S.LOCGOV_CODE, CONCAT(L.UPPER_LOCGOV_NM,' ',L.LOCGOV_NM) AS LOCGOV_NM , IFNULL(LRGM.SORT_SEQ, 5) AS SORT_SEQ1 FROM OP_ITEM I JOIN OP_SELLER S ON I.SELLER_ID = S.SELLER_ID JOIN G_LOCGOV L ON S.LOCGOV_CODE = L.LOCGOV_CODE JOIN OP_ITEM_CATEGORY IC ON I.ITEM_ID = IC.ITEM_ID JOIN OP_CATEGORY C ON IC.CATEGORY_ID = C.CATEGORY_ID JOIN OP_CATEGORY_GROUP G ON C.CATEGORY_GROUP_ID = G.CATEGORY_GROUP_ID LEFT JOIN OP_ITEM_OPTION_SOLDOUT T ON I.ITEM_ID = T.ITEM_ID LEFT JOIN G_LCLGV_RPRS_GDS_MNG LRGM ON S.LOCGOV_CODE = LRGM.LCLGV_CD AND I.ITEM_ID = LRGM.GDS_ID WHERE 1=1 AND I.DATA_STATUS_CODE = '1' AND I.DISPLAY_FLAG = 'Y' AND I.ITEM_DATA_TYPE = '1' AND I.ITEM_TYPE IN ('1', '3') AND I.PRIVATE_TYPE IN ('000') AND S.STATUS_CODE = '2' AND C.CATEGORY_FLAG = 'Y' AND G.CATEGORY_GROUP_FLAG = 'Y'
AND 'N' = ( CASE WHEN I.SOLD_OUT = '1' THEN 'Y' WHEN I.ITEM_OPTION_FLAG = 'N' AND I.STOCK_FLAG = 'Y' AND I.STOCK_QUANTITY = 0 THEN 'Y' WHEN I.ITEM_OPTION_FLAG = 'Y' AND I.ITEM_OPTION_TYPE = 'T' AND I.STOCK_FLAG = 'Y' AND I.STOCK_QUANTITY = 0 THEN 'Y' WHEN I.ITEM_OPTION_FLAG = 'Y' AND T.ITEM_OPTION_SOLD_OUT_FLAG = 'Y' THEN 'Y' ELSE 'N' END )
AND ( I2.ITEM_NAME LIKE CONCAT('%', replace(#{keyword},' ', '%'), '%') OR (I2.ITEM_KEYWORD LIKE CONCAT('%', replace(#{keyword}, ' ', '%') ,'%')) )
AND G.CODE = #{group}
AND C.CATEGORY_URL = #{category}
AND C.CATEGORY_CLASS1 = #{categoryClass1}
AND C.CATEGORY_CLASS1 = #{categoryClass1} AND C.CATEGORY_CLASS2 = #{categoryClass2}
AND C.CATEGORY_CLASS1 = #{categoryClass1} AND C.CATEGORY_CLASS2 = #{categoryClass2} AND C.CATEGORY_CLASS3 = #{categoryClass3}
AND C.CATEGORY_CLASS1 = #{categoryClass1} AND C.CATEGORY_CLASS2 = #{categoryClass2} AND C.CATEGORY_CLASS3 = #{categoryClass3} AND C.CATEGORY_CLASS4 = #{categoryClass4}
AND I.SALE_PRICE >= 50000
AND I.SALE_PRICE BETWEEN 30000 AND 50000
AND I.SALE_PRICE BETWEEN 10000 AND 30000
AND I.SALE_PRICE <= #{price}
AND L.UPPER_LOCGOV_CODE = SUBSTR(#{locgov}, 2)
AND S.LOCGOV_CODE = #{locgov}
GROUP BY I.ITEM_ID
ORDER BY SORT_SEQ1 ASC
, I.CREATED_DATE DESC
, I.CREATED_DATE ASC
, I.SALE_PRICE DESC
, I.SALE_PRICE ASC
ORDER BY I.CREATED_DATE DESC
, I.CREATED_DATE DESC

/* saleson.shop.item.ItemFrontMapper.getFrontItemCountBySeason 제철식품관 목록 개수 조회 */
SELECT COUNT(1) FROM ( SELECT 1 FROM ( SELECT I.ITEM_ID , I.SELLER_ID , IC.CATEGORY_ID FROM OP_ITEM I , OP_ITEM_CATEGORY IC WHERE 1=1 AND I.DATA_STATUS_CODE = '1' AND I.DISPLAY_FLAG = 'Y' AND I.ITEM_DATA_TYPE = '1' AND I.ITEM_TYPE IN ('1', '3') AND I.PRIVATE_TYPE IN ('000') AND IC.ITEM_ID = I.ITEM_ID ) I , OP_SELLER S , OP_CATEGORY C , OP_CATEGORY_GROUP CG , G_SEASON_FOOD_ITEM SFI , G_LOCGOV L WHERE 1=1 AND I.SELLER_ID = S.SELLER_ID AND S.STATUS_CODE = '2' AND C.CATEGORY_GROUP_ID = CG.CATEGORY_GROUP_ID AND I.CATEGORY_ID = C.CATEGORY_ID and SFI.ITEM_ID = I.ITEM_ID AND SFI.SEASON_FOOD_MONTH = #{month} AND CG.CODE IN ('farm', 'aquatic') AND L.LOCGOV_CODE = S.LOCGOV_CODE
AND L.UPPER_LOCGOV_CODE IN (SUBSTR(#{locgov}, 2))
AND S.LOCGOV_CODE = #{locgov}
GROUP BY I.ITEM_ID )

/* saleson.shop.item.ItemFrontMapper.getFrontItemListBySeason 제철식품관 목록 조회 */
SELECT * FROM( SELECT I.*, ( CASE WHEN I.SOLD_OUT = '1' THEN 'Y' WHEN I.ITEM_OPTION_FLAG = 'N' AND I.STOCK_FLAG = 'Y' AND I.STOCK_QUANTITY = 0 THEN 'Y' WHEN I.ITEM_OPTION_FLAG = 'Y' AND I.ITEM_OPTION_TYPE = 'T' AND I.STOCK_FLAG = 'Y' AND I.STOCK_QUANTITY = 0 THEN 'Y' WHEN I.ITEM_OPTION_FLAG = 'Y' AND T.ITEM_OPTION_SOLD_OUT_FLAG = 'Y' THEN 'Y' ELSE 'N' END ) AS ITEM_SOLD_OUT_FLAG, S.LOCGOV_CODE, IFNULL(T.ITEM_OPTION_SOLD_OUT_FLAG,'N') AS ITEM_OPTION_SOLD_OUT_FLAG, CONCAT(L.UPPER_LOCGOV_NM,' ',L.LOCGOV_NM) AS LOCGOV_NM FROM ( SELECT I.ITEM_ID, I.SELLER_ID, I.ITEM_CODE, I.ITEM_USER_CODE, I.ITEM_NAME, I.ITEM_SUMMARY, I.ITEM_DATA_TYPE, I.ITEM_TYPE, I.ITEM_NEW_FLAG, I.ITEM_LABEL, I.ITEM_TYPE1, I.ITEM_TYPE2, I.ITEM_TYPE3, I.ITEM_TYPE4, I.ITEM_TYPE5, I.ITEM_TYPE6, I.ITEM_TYPE7, I.ITEM_TYPE8, I.ITEM_TYPE9, I.ITEM_TYPE10, I.SOLD_OUT, I.STOCK_FLAG, I.STOCK_QUANTITY, I.TAX_TYPE, I.ITEM_PRICE, I.COST_PRICE, I.SUPPLY_PRICE, I.SALE_PRICE, I.ADULT_ITEM_YN, I.MOBILE_ITEM_YN, I.ITEM_IMAGE, I.ITEM_OPTION_FLAG, I.ITEM_OPTION_TYPE, I.ITEM_OPTION_TITLE1, I.ITEM_OPTION_TITLE2, I.ITEM_OPTION_TITLE3, I.DATA_STATUS_CODE, I.DISPLAY_FLAG, I.STOCK_CODE, I.STOCK_SCHEDULE_AUTO_FLAG, I.STOCK_SCHEDULE_TYPE, I.STOCK_SCHEDULE_DATE, I.STOCK_SCHEDULE_TEXT, I.ORDER_MIN_QUANTITY, I.ORDER_MAX_QUANTITY, I.SALE_QUANTITY, I.CREATED_DATE, IC.CATEGORY_ID FROM OP_ITEM I , OP_ITEM_CATEGORY IC WHERE 1=1 AND I.DATA_STATUS_CODE = '1' AND I.DISPLAY_FLAG = 'Y' AND I.ITEM_DATA_TYPE = '1' AND I.ITEM_TYPE IN ('1', '3') AND I.PRIVATE_TYPE IN ('000') AND IC.ITEM_ID = I.ITEM_ID ) I , OP_SELLER S , OP_CATEGORY C , OP_CATEGORY_GROUP CG , G_SEASON_FOOD_ITEM SFI , OP_ITEM_OPTION_SOLDOUT T , G_LOCGOV L WHERE 1=1 AND I.SELLER_ID = S.SELLER_ID AND S.STATUS_CODE = '2' AND C.CATEGORY_GROUP_ID = CG.CATEGORY_GROUP_ID AND I.CATEGORY_ID = C.CATEGORY_ID and SFI.ITEM_ID = I.ITEM_ID AND SFI.SEASON_FOOD_MONTH = #{month} AND CG.CODE IN ('farm', 'aquatic') AND I.ITEM_ID = T.ITEM_ID(+) AND L.LOCGOV_CODE = S.LOCGOV_CODE
AND L.UPPER_LOCGOV_CODE IN (SUBSTR(#{locgov}, 2))
AND S.LOCGOV_CODE = #{locgov}
GROUP BY I.ITEM_ID ) DERIVED_TABLE ORDER BY CASE WHEN ITEM_SOLD_OUT_FLAG = 'Y' OR ITEM_OPTION_SOLD_OUT_FLAG = 'Y' THEN 1 ELSE 0 END, CREATED_DATE DESC

/* saleson.shop.item.ItemFrontMapper.getFrontItemCountByCommunity 마을기업 목록 개수 조회 */
SELECT COUNT(1) FROM ( SELECT 1 FROM ( SELECT I.ITEM_ID , I.SELLER_ID , IC.CATEGORY_ID FROM OP_ITEM I JOIN OP_ITEM_CATEGORY IC ON IC.ITEM_ID = I.ITEM_ID LEFT JOIN OP_ITEM_OPTION_SOLDOUT T ON I.ITEM_ID = T.ITEM_ID WHERE 1=1 AND I.DATA_STATUS_CODE = '1' AND I.DISPLAY_FLAG = 'Y' AND I.ITEM_DATA_TYPE = '1' AND I.ITEM_TYPE IN ('1', '3') AND I.PRIVATE_TYPE IN ('000') AND 'N' = ( CASE WHEN I.SOLD_OUT = '1' THEN 'Y' WHEN I.ITEM_OPTION_FLAG = 'N' AND I.STOCK_FLAG = 'Y' AND I.STOCK_QUANTITY = 0 THEN 'Y' WHEN I.ITEM_OPTION_FLAG = 'Y' AND I.ITEM_OPTION_TYPE = 'T' AND I.STOCK_FLAG = 'Y' AND I.STOCK_QUANTITY = 0 THEN 'Y' WHEN I.ITEM_OPTION_FLAG = 'Y' AND T.ITEM_OPTION_SOLD_OUT_FLAG = 'Y' THEN 'Y' ELSE 'N' END ) ) I , OP_SELLER S , OP_CATEGORY C , OP_CATEGORY_GROUP CG , G_LOCGOV L WHERE 1=1 AND I.SELLER_ID = S.SELLER_ID AND S.STATUS_CODE = '2' AND C.CATEGORY_GROUP_ID = CG.CATEGORY_GROUP_ID AND I.CATEGORY_ID = C.CATEGORY_ID AND L.LOCGOV_CODE = S.LOCGOV_CODE AND S.COMMUNITY_BUSINESS_YN = 'Y'
AND L.UPPER_LOCGOV_CODE IN (SUBSTR(#{locgov}, 2))
AND S.LOCGOV_CODE = #{locgov}
GROUP BY I.ITEM_ID )

/* saleson.shop.item.ItemFrontMapper.getFrontItemListByCommunity 마을기업 목록 조회 */
SELECT I.ITEM_ID, I.SELLER_ID, I.ITEM_CODE, I.ITEM_USER_CODE, I.ITEM_NAME, I.ITEM_SUMMARY, I.ITEM_DATA_TYPE, I.ITEM_TYPE, I.ITEM_NEW_FLAG, I.ITEM_LABEL, I.ITEM_TYPE1, I.ITEM_TYPE2, I.ITEM_TYPE3, I.ITEM_TYPE4, I.ITEM_TYPE5, I.ITEM_TYPE6, I.ITEM_TYPE7, I.ITEM_TYPE8, I.ITEM_TYPE9, I.ITEM_TYPE10, I.SOLD_OUT, I.STOCK_FLAG, I.STOCK_QUANTITY, I.TAX_TYPE, I.ITEM_PRICE, I.COST_PRICE, I.SUPPLY_PRICE, I.SALE_PRICE, I.ADULT_ITEM_YN, I.MOBILE_ITEM_YN, I.ITEM_IMAGE, I.ITEM_OPTION_FLAG, I.ITEM_OPTION_TYPE, I.ITEM_OPTION_TITLE1, I.ITEM_OPTION_TITLE2, I.ITEM_OPTION_TITLE3, I.DATA_STATUS_CODE, I.DISPLAY_FLAG, I.STOCK_CODE, I.STOCK_SCHEDULE_AUTO_FLAG, I.STOCK_SCHEDULE_TYPE, I.STOCK_SCHEDULE_DATE, I.STOCK_SCHEDULE_TEXT, I.ORDER_MIN_QUANTITY, I.ORDER_MAX_QUANTITY, I.SALE_QUANTITY, I.CREATED_DATE,
S.SELLER_NAME, S.LOGIN_ID AS SELLER_LOGIN_ID, S.COMPANY_NAME AS SELLER_COMPANY_NAME, S.COMMISSION_RATE AS SELLER_COMMISSION_RATE, S.LOCGOV_CODE, CONCAT(L.UPPER_LOCGOV_NM,' ',L.LOCGOV_NM) AS LOCGOV_NM, S.COMMUNITY_BUSINESS_YN FROM ( SELECT T_I.ITEM_ID FROM ( SELECT I2.ITEM_ID , I2.SELLER_ID , I2.SALE_PRICE , I2.CREATED_DATE FROM OP_ITEM I2 LEFT JOIN OP_ITEM_OPTION_SOLDOUT T ON I2.ITEM_ID = T.ITEM_ID JOIN OP_SELLER OS ON I2.SELLER_ID = OS.SELLER_ID AND OS.COMMUNITY_BUSINESS_YN = 'Y' JOIN G_LOCGOV L2 ON OS.LOCGOV_CODE = L2.LOCGOV_CODE
AND L2.UPPER_LOCGOV_CODE IN (SUBSTR(#{locgov}, 2))
AND OS.LOCGOV_CODE = #{locgov}
WHERE I2.DATA_STATUS_CODE = '1' AND I2.DISPLAY_FLAG = 'Y' AND I2.ITEM_DATA_TYPE = '1' AND I2.ITEM_TYPE IN ('1', '3') AND I2.PRIVATE_TYPE IN ('000') AND 'N' = ( CASE WHEN I2.SOLD_OUT = '1' THEN 'Y' WHEN I2.ITEM_OPTION_FLAG = 'N' AND I2.STOCK_FLAG = 'Y' AND I2.STOCK_QUANTITY = 0 THEN 'Y' WHEN I2.ITEM_OPTION_FLAG = 'Y' AND I2.ITEM_OPTION_TYPE = 'T' AND I2.STOCK_FLAG = 'Y' AND I2.STOCK_QUANTITY = 0 THEN 'Y' WHEN I2.ITEM_OPTION_FLAG = 'Y' AND T.ITEM_OPTION_SOLD_OUT_FLAG = 'Y' THEN 'Y' ELSE 'N' END )
ORDER BY I2.CREATED_DATE DESC
) T_I JOIN OP_ITEM_CATEGORY IC ON T_I.ITEM_ID = IC.ITEM_ID JOIN OP_CATEGORY C ON IC.CATEGORY_ID = C.CATEGORY_ID JOIN OP_CATEGORY_GROUP G ON C.CATEGORY_GROUP_ID = G.CATEGORY_GROUP_ID JOIN OP_SELLER S2 ON T_I.SELLER_ID = S2.SELLER_ID JOIN G_LOCGOV L2 ON S2.LOCGOV_CODE = L2.LOCGOV_CODE WHERE 1=1 AND C.CATEGORY_FLAG = 'Y' AND G.CATEGORY_GROUP_FLAG = 'Y' AND S2.STATUS_CODE = '2'
GROUP BY T_I.ITEM_ID
ORDER BY T_I.CREATED_DATE DESC
) T_A JOIN OP_ITEM I ON T_A.ITEM_ID = I.ITEM_ID JOIN OP_SELLER S ON I.SELLER_ID = S.SELLER_ID JOIN G_LOCGOV L ON S.LOCGOV_CODE = L.LOCGOV_CODE WHERE 1=1 ORDER BY I.CREATED_DATE DESC

/* saleson.shop.item.ItemFrontMapper.getFrontItemCountBySpeciality 특산물관 목록 개수 조회 */
SELECT COUNT(1) FROM ( SELECT 1 FROM ( SELECT I.ITEM_ID , I.SELLER_ID FROM OP_ITEM I , OP_ITEM_CATEGORY IC WHERE 1=1 AND I.DATA_STATUS_CODE = '1' AND I.DISPLAY_FLAG = 'Y' AND I.ITEM_DATA_TYPE = '1' AND I.ITEM_TYPE IN ('1', '3') AND I.PRIVATE_TYPE IN ('000') AND IC.ITEM_ID = I.ITEM_ID ) I , OP_SELLER S , G_SPCL_ITEM_MNG SIM , G_SPCL_ITEM SI , OP_ITEM_OPTION_SOLDOUT T , G_LOCGOV L WHERE SIM.SPCL_ITEM_MNG_ID = SI.SPCL_ITEM_MNG_ID AND I.ITEM_ID = SI.ITEM_ID AND I.SELLER_ID = S.SELLER_ID AND S.STATUS_CODE = '2'
AND L.UPPER_LOCGOV_CODE IN (SUBSTR(#{locgov}, 2))
AND SIM.LOCGOV_CODE = #{locgov}
AND L.LOCGOV_CODE = S.LOCGOV_CODE AND L.LOCGOV_CODE = SIM.LOCGOV_CODE AND I.ITEM_ID = T.ITEM_ID(+) )

/* saleson.shop.item.ItemFrontMapper.getFrontItemListBySpeciality 특산물관 목록 조회 */
SELECT I.*, ( CASE WHEN I.SOLD_OUT = '1' THEN 'Y' WHEN I.ITEM_OPTION_FLAG = 'N' AND I.STOCK_FLAG = 'Y' AND I.STOCK_QUANTITY = 0 THEN 'Y' WHEN I.ITEM_OPTION_FLAG = 'Y' AND I.ITEM_OPTION_TYPE = 'T' AND I.STOCK_FLAG = 'Y' AND I.STOCK_QUANTITY = 0 THEN 'Y' WHEN I.ITEM_OPTION_FLAG = 'Y' AND T.ITEM_OPTION_SOLD_OUT_FLAG = 'Y' THEN 'Y' ELSE 'N' END ) AS ITEM_SOLD_OUT_FLAG, SIM.LOCGOV_CODE, IFNULL(T.ITEM_OPTION_SOLD_OUT_FLAG,'N') AS ITEM_OPTION_SOLD_OUT_FLAG, CONCAT(L.UPPER_LOCGOV_NM,' ',L.LOCGOV_NM) AS LOCGOV_NM FROM ( SELECT I.ITEM_ID, I.SELLER_ID, I.ITEM_CODE, I.ITEM_USER_CODE, I.ITEM_NAME, I.ITEM_SUMMARY, I.ITEM_DATA_TYPE, I.ITEM_TYPE, I.ITEM_NEW_FLAG, I.ITEM_LABEL, I.ITEM_TYPE1, I.ITEM_TYPE2, I.ITEM_TYPE3, I.ITEM_TYPE4, I.ITEM_TYPE5, I.ITEM_TYPE6, I.ITEM_TYPE7, I.ITEM_TYPE8, I.ITEM_TYPE9, I.ITEM_TYPE10, I.SOLD_OUT, I.STOCK_FLAG, I.STOCK_QUANTITY, I.TAX_TYPE, I.ITEM_PRICE, I.COST_PRICE, I.SUPPLY_PRICE, I.SALE_PRICE, I.ADULT_ITEM_YN, I.MOBILE_ITEM_YN, I.ITEM_IMAGE, I.ITEM_OPTION_FLAG, I.ITEM_OPTION_TYPE, I.ITEM_OPTION_TITLE1, I.ITEM_OPTION_TITLE2, I.ITEM_OPTION_TITLE3, I.DATA_STATUS_CODE, I.DISPLAY_FLAG, I.STOCK_CODE, I.STOCK_SCHEDULE_AUTO_FLAG, I.STOCK_SCHEDULE_TYPE, I.STOCK_SCHEDULE_DATE, I.STOCK_SCHEDULE_TEXT, I.ORDER_MIN_QUANTITY, I.ORDER_MAX_QUANTITY, I.SALE_QUANTITY, I.CREATED_DATE, IC.CATEGORY_ID FROM OP_ITEM I , OP_ITEM_CATEGORY IC WHERE 1=1 AND I.DATA_STATUS_CODE = '1' AND I.DISPLAY_FLAG = 'Y' AND I.ITEM_DATA_TYPE = '1' AND I.ITEM_TYPE IN ('1', '3') AND I.PRIVATE_TYPE IN ('000') AND IC.ITEM_ID = I.ITEM_ID ) I , OP_SELLER S , G_SPCL_ITEM_MNG SIM , G_SPCL_ITEM SI , OP_ITEM_OPTION_SOLDOUT T , G_LOCGOV L WHERE SIM.SPCL_ITEM_MNG_ID = SI.SPCL_ITEM_MNG_ID AND I.ITEM_ID = SI.ITEM_ID AND I.SELLER_ID = S.SELLER_ID AND S.STATUS_CODE = '2'
AND L.UPPER_LOCGOV_CODE IN (SUBSTR(#{locgov}, 2))
AND SIM.LOCGOV_CODE = #{locgov}
AND L.LOCGOV_CODE = S.LOCGOV_CODE AND L.LOCGOV_CODE = SIM.LOCGOV_CODE AND I.ITEM_ID = T.ITEM_ID(+) ORDER BY I.CREATED_DATE DESC

/* saleson.shop.item.ItemFrontMapper.getFrontItemTypelListNew 지자체몰(카테고리, 금액별) 목록 조회(국정자원진단 제시 코드) */ SELECT I.ITEM_ID, I.SELLER_ID, I.ITEM_CODE, I.ITEM_USER_CODE, I.ITEM_NAME, I.ITEM_SUMMARY, I.ITEM_DATA_TYPE, I.ITEM_TYPE, I.ITEM_NEW_FLAG, I.ITEM_LABEL, I.ITEM_TYPE1, I.ITEM_TYPE2, I.ITEM_TYPE3, I.ITEM_TYPE4, I.ITEM_TYPE5, I.ITEM_TYPE6, I.ITEM_TYPE7, I.ITEM_TYPE8, I.ITEM_TYPE9, I.ITEM_TYPE10, I.SOLD_OUT, I.STOCK_FLAG, I.STOCK_QUANTITY, I.TAX_TYPE, I.ITEM_PRICE, I.COST_PRICE, I.SUPPLY_PRICE, I.SALE_PRICE, I.ADULT_ITEM_YN, I.MOBILE_ITEM_YN, I.ITEM_IMAGE, I.ITEM_OPTION_FLAG, I.ITEM_OPTION_TYPE, I.ITEM_OPTION_TITLE1, I.ITEM_OPTION_TITLE2, I.ITEM_OPTION_TITLE3, I.DATA_STATUS_CODE, I.DISPLAY_FLAG, I.STOCK_CODE, I.STOCK_SCHEDULE_AUTO_FLAG, I.STOCK_SCHEDULE_TYPE, I.STOCK_SCHEDULE_DATE, I.STOCK_SCHEDULE_TEXT, I.ORDER_MIN_QUANTITY, I.ORDER_MAX_QUANTITY, I.SALE_QUANTITY, I.CREATED_DATE,
S.SELLER_NAME, S.LOGIN_ID AS SELLER_LOGIN_ID, S.COMPANY_NAME AS SELLER_COMPANY_NAME, S.COMMISSION_RATE AS SELLER_COMMISSION_RATE, S.LOCGOV_CODE, CONCAT(L.UPPER_LOCGOV_NM,' ',L.LOCGOV_NM) AS LOCGOV_NM FROM ( SELECT T_I.ITEM_ID FROM ( SELECT I2.ITEM_ID , I2.SELLER_ID , I2.SALE_PRICE , I2.CREATED_DATE FROM OP_ITEM I2 LEFT JOIN OP_ITEM_OPTION_SOLDOUT T ON I2.ITEM_ID = T.ITEM_ID WHERE I2.DATA_STATUS_CODE = '1' AND I2.DISPLAY_FLAG = 'Y' AND I2.ITEM_DATA_TYPE = '1' AND I2.ITEM_TYPE IN ('1', '3') AND I2.PRIVATE_TYPE IN ('000')
AND 'N' = ( CASE WHEN I2.SOLD_OUT = '1' THEN 'Y' WHEN I2.ITEM_OPTION_FLAG = 'N' AND I2.STOCK_FLAG = 'Y' AND I2.STOCK_QUANTITY = 0 THEN 'Y' WHEN I2.ITEM_OPTION_FLAG = 'Y' AND I2.ITEM_OPTION_TYPE = 'T' AND I2.STOCK_FLAG = 'Y' AND I2.STOCK_QUANTITY = 0 THEN 'Y' WHEN I2.ITEM_OPTION_FLAG = 'Y' AND T.ITEM_OPTION_SOLD_OUT_FLAG = 'Y' THEN 'Y' ELSE 'N' END )
AND I2.SALE_PRICE >= 50000
AND I2.SALE_PRICE BETWEEN 30000 AND 50000
AND I2.SALE_PRICE BETWEEN 10000 AND 30000
AND I2.SALE_PRICE <= #{price}
AND ( I2.ITEM_NAME LIKE CONCAT('%', replace(#{keyword},' ', '%'), '%') OR (I2.ITEM_KEYWORD LIKE CONCAT('%', replace(#{keyword}, ' ', '%') ,'%')) )
ORDER BY I2.CREATED_DATE DESC
ORDER BY I2.CREATED_DATE DESC
) T_I JOIN OP_ITEM_CATEGORY IC ON T_I.ITEM_ID = IC.ITEM_ID JOIN OP_CATEGORY C ON IC.CATEGORY_ID = C.CATEGORY_ID JOIN OP_CATEGORY_GROUP G ON C.CATEGORY_GROUP_ID = G.CATEGORY_GROUP_ID JOIN OP_SELLER S2 ON T_I.SELLER_ID = S2.SELLER_ID JOIN G_LOCGOV L2 ON S2.LOCGOV_CODE = L2.LOCGOV_CODE WHERE 1=1 AND C.CATEGORY_FLAG = 'Y' AND G.CATEGORY_GROUP_FLAG = 'Y' AND S2.STATUS_CODE = '2'
AND G.CODE = #{group}
AND C.CATEGORY_URL = #{category}
AND C.CATEGORY_CLASS1 = #{categoryClass1}
AND C.CATEGORY_CLASS1 = #{categoryClass1} AND C.CATEGORY_CLASS2 = #{categoryClass2}
AND C.CATEGORY_CLASS1 = #{categoryClass1} AND C.CATEGORY_CLASS2 = #{categoryClass2} AND C.CATEGORY_CLASS3 = #{categoryClass3}
AND C.CATEGORY_CLASS1 = #{categoryClass1} AND C.CATEGORY_CLASS2 = #{categoryClass2} AND C.CATEGORY_CLASS3 = #{categoryClass3} AND C.CATEGORY_CLASS4 = #{categoryClass4}
AND L2.UPPER_LOCGOV_CODE = SUBSTR(#{locgov}, 2)
AND S2.LOCGOV_CODE = #{locgov}
GROUP BY T_I.ITEM_ID
ORDER BY T_I.CREATED_DATE DESC
ORDER BY T_I.CREATED_DATE DESC
) T_A JOIN OP_ITEM I ON T_A.ITEM_ID = I.ITEM_ID JOIN OP_SELLER S ON I.SELLER_ID = S.SELLER_ID JOIN G_LOCGOV L ON S.LOCGOV_CODE = L.LOCGOV_CODE WHERE 1=1

/* saleson.shop.item.ItemFrontMapper.getItemImagesExplainByLinkView	상품의 이미지 설명을 조회(링크뷰) */
	SELECT IMG_SEQ AS IMAGES_INDEXES
		   , IMG_EXPLN AS IMAGES_VALUES
	FROM G_GDS_IMG_EXPLN_LINK_VIEW
	WHERE GDS_USER_CD = #{itemUserCode}
